  /\bflorida\s+keys|\b(?:upper|middle|lower)\s+keys|\bkey\s+(?:west|largo|colony)|\bislamorada|\bsugarloaf|\b(?:marathon|big\s+pine)\s+(?:key|fishing)|\bkeys\s+(?:fishing|fish\s+report|bragboard)/i.test(text)?'keys':null;
